/// `FK-05`: The gate never admits an origin other than Forge when no grant record exists
#[test]
fn forge_kernel_fk_05() {
    pinned(
        "breaksGateNoRecordOnlyForge",
        "body: ((((project request hasRecord) =? 0) && (not ((project request origin) =? (ForgeKernel::originForge)))) && ((ForgeKernel::gateAllows request) =? 1))",
        "noRecordOnlyForgeHolds",
    );
}

/// `FK-06`: The gate never admits a fetch when no grant record exists
#[test]
fn forge_kernel_fk_06() {
    pinned(
        "breaksGateNoRecordNoFetch",
        "body: ((((project request hasRecord) =? 0) && ((project request effect) =? (ForgeKernel::effectFetch))) && ((ForgeKernel::gateAllows request) =? 1))",
        "noRecordNoFetchHolds",
    );
}

/// `FK-07`: The gate never admits a resource its grant record denies
#[test]
fn forge_kernel_fk_07() {
    pinned(
        "breaksGateDenyWins",
        "body: ((((project request hasRecord) =? 1) && ((project request denied) =? 1)) && ((ForgeKernel::gateAllows request) =? 1))",
        "denyWinsHolds",
    );
}

/// `FK-08`: The gate never admits a preview or a published app without a grant
#[test]
fn forge_kernel_fk_08() {
    pinned(
        "breaksGateOutsideForgeNeedsGrant",
        "body: (((not ((project request origin) =? (ForgeKernel::originForge))) && (not ((project request granted) =? 1))) && ((ForgeKernel::gateAllows request) =? 1))",
        "outsideForgeNeedsGrantHolds",
    );
}

/// `FK-09`: The gate never lets a preview fetch without a grant
#[test]
fn forge_kernel_fk_09() {
    pinned(
        "breaksGatePreviewNoNetworkWithoutGrant",
        "body: (((((project request origin) =? (ForgeKernel::originPreview)) && ((project request effect) =? (ForgeKernel::effectFetch))) && (not ((project request granted) =? 1))) && ((ForgeKernel::gateAllows request) =? 1))",
        "previewNoNetworkWithoutGrantHolds",
    );
}

